\label{def:cas}
{\normalfont (\textbf{Conditional Adjustment Set for MPDAGs, PAGs})}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a causal MPDAG or PAG $\g$. Then $\mb{S}$ is a conditional adjustment set relative to $(\mb{X},\mb{Y},\mb{Z})$ in $\g$ if for any density $f$ consistent with $\g$ 
    \begin{align}
        f(\mb{y}|do(\mb{x}), \mb{z}) = 
        \begin{cases} 
            f(\mb{y} | \mb{x}, \mb{z}) & \mb{S}=\emptyset \\
            \int f(\mb{y} | \mb{x}, \mb{z}, \mb{s}) f(\mb{s}|\mb{z}) \mathop{}\!\mathrm{d} \mb{s} & \mb{S}\neq\emptyset.
        \end{cases}
    \end{align}

\begin{align}
        f(\mb{y}|do(\mb{x}), \mb{z}) = 
        \begin{cases} 
            f(\mb{y} | \mb{x}, \mb{z}) & \mb{S}=\emptyset \\
            \int f(\mb{y} | \mb{x}, \mb{z}, \mb{s}) f(\mb{s}|\mb{z}) \mathop{}\!\mathrm{d} \mb{s} & \mb{S}\neq\emptyset.
        \end{cases}
    \end{align}

\label{thm:cac-cas}
{\normalfont (\textbf{Completeness, Soundness of Conditional Adjustment Criterion for MPDAGs})}
    Let $\mb{X,Y}, \mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a causal MPDAG $\g$, where $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$. Then $\mb{S}$ is a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g$ (Definition \ref{def:cas}) if and only if $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g$ (Definition \ref{def:cac}).

First note the following facts. 
\begin{enumerate}[label=(\roman*)]
    \item Every proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed edge. \label{pf:cac-cas-1}
    \item $\mb{Z} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$ in every DAG $\g[D]$ in $[\g]$. \label{pf:cac-cas-2} 
    \item $\mb{Z} \cap \fb{\g} = \emptyset$. \label{pf:cac-cas-3} 
\end{enumerate}

We have that \ref{pf:cac-cas-1} holds in either direction -- by definition ($\Leftarrow$) or by Proposition \ref{prop:id-necessary} (Supp.\ \ref{supp:necessary}) ($\Rightarrow$). Then Lemmas \ref{lem:equiv-z-mpdag} and \ref{lem:henckel-e6} (Supp.\ \ref{supp:existing}) imply \ref{pf:cac-cas-2} and \ref{pf:cac-cas-3}, respectively, given $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$ and \ref{pf:cac-cas-1}.

Now consider the following statements.
\begin{enumerate}[label=(\alph*)]
    \item $\mb{S}$ is a conditional adjustment set relative to $(\mb{X},\mb{Y},\mb{Z})$ in $\g$. \label{pf:cac-cas-a}

    \item $\mb{S}$ is a conditional adjustment set relative to $(\mb{X},\mb{Y},\mb{Z})$ in each DAG in $[\g]$ -- were the DAG to be causal.\label{pf:cac-cas-b}

    \item $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in each DAG in $[\g]$. \label{pf:cac-cas-c}

    \item $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g$. \label{pf:cac-cas-d}
\end{enumerate}

By definition, \ref{pf:cac-cas-a} $\Leftrightarrow$ \ref{pf:cac-cas-b}. Then \ref{pf:cac-cas-b} $\Leftrightarrow$ \ref{pf:cac-cas-c} by Theorems \ref{thm:completeness} and \ref{thm:soundness} (Supp.\ \ref{supp:adjustment}) and the fact that the conditional adjustment criterion does not require a causal DAG. Lastly, by the facts above and by applying Lemmas \ref{lem:equiv-forb} and \ref{lem:equiv-block} (Supp.\ \ref{supp:existing}) in turn, \ref{pf:cac-cas-c} $\Leftrightarrow$ \ref{pf:cac-cas-d}.


\label{ex:cas-empty}
{\normalfont (\textbf{Empty Conditional Adjustment Set.})}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:examples-a} \footnote{Compare to Figure 5(a) of \cite{perkovic2020identifying}.}, and let $\mb{X} = \{X\}$, $\mb{Y}=\{Y\}$, and $\mb{Z}=\{V_1, V_2\}$. Note that $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$ and that every possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed edge.

    Let $\mb{S} = \emptyset$. Note that $\mb{S} \cap (\mb{X} \cup \mb{Y} \cup \mb{Z}) = \emptyset$, $\mb{S} \cap \fb{\g} = \emptyset$, and $\mb{S} \cup \mb{Z}$ blocks all non-causal definite status paths from $\mb{X}$ to $\mb{Y}$. Thus, $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X},\mb{Y},\mb{Z})$ in $\g$, and by Theorem \ref{thm:cac-cas}, $f(\mb{y}|do(\mb{x}), \mb{z}) = f(y | x, v_1, v_2)$.

\label{ex:cas-nonempty}
{\normalfont (\textbf{Only Nonempty Conditional Adjustment Sets.})}
    Again let $\g$ be the causal MPDAG in Figure \ref{fig:examples-a}, where $\mb{X} = \{X\}$ and $\mb{Y}=\{Y\}$. But now let $\mb{Z}=\{V_1\}$. We still have that $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$ and that every possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed edge.

    Note that if we let $\mb{S} = \emptyset$, $\mb{S} \cup \mb{Z}$ does not block the path $X \gets V_2 \to Y$, which is a proper non-causal definite status path from $\mb{X}$ to $\mb{Y}$. Thus, the empty set is not a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g$.

    Consider, instead, the set $\mb{S} = \{V_2\}$. Note that $\mb{S} \cap (\mb{X} \cup \mb{Y} \cup \mb{Z}) = \emptyset$, $\mb{S} \cap \fb{\g} = \emptyset$, and $\mb{S} \cup \mb{Z}$ blocks all non-causal definite status paths from $\mb{X}$ to $\mb{Y}$. Thus, $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g$, and by Theorem \ref{thm:cac-cas}, $f(\mb{y}|do(\mb{x}), \mb{z}) = \int f(y | x, v_1, v_2) f(v_2|v_1) \mathop{}\!\mathrm{d} v_2$.

\label{ex:cas-descendants}
{\normalfont (\textbf{Conditional Adjustment Set Contains Descendants of $\mb{X}$.})}
    Let $\g$ be the causal DAG (and therefore, MPDAG) in Figure \ref{fig:examples-b} \footnote{Compare to Figure 6(a) of \cite{perkovic2018complete}.}, where we assume $L$ is a variable that cannot be measured. Define $\mb{X} = \{X_1,X_2\}$, $\mb{Y}=\{Y\}$, and $\mb{Z} = \{Z\}$. Note that $\mb{Z} \cap \mathrm{De}(\mb{X}, \g) = \emptyset$.

    Consider the set $\mb{S} = \{S,W\}$. Note that $\mb{S} \cap (\mb{X} \cup \mb{Y} \cup \mb{Z}) = \emptyset$, $\mb{S} \cap \fb{\g} = \emptyset$, and $\mb{S}$ blocks all proper non-causal paths from $\mb{X}$ to $\mb{Y}$ in $\g$. Hence, $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g$, and by Theorem \ref{thm:cac-cas}, $f(\mb{y}|do(\mb{x}), \mb{z}) = \int f(y | x_1,x_2,z,s,w) f(s,w|z) \mathop{}\!\mathrm{d} s \mathop{}\!\mathrm{d} w$.

\label{ex:nocas-noamen}
{\normalfont (\textbf{No Conditional Adjustment Set, Effect Non-identifiable}.)}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:examples-c}, and let $\mb{X} = \{X\}$, $\mb{Y}=\{Y\}$, and $\mb{Z}=\{V_3\}$. Note that $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$. However, $X - V_1 \to V_2 \to Y$ is a proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ that starts with an undirected edge. Thus, by Theorem \ref{thm:cac-cas}, there can be no conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g$. In fact, by Proposition \ref{prop:id-necessary} (Supp.\ \ref{supp:necessary}), $f(\mb{y}| do(\mb{x}), \mb{z})$ is not identifiable in $\g$ using any method.

