\label{lem:comparison}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in an MPDAG $\g$, where $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$. Then we have the following.
    \begin{enumerate}[label=\emph{(\alph*)}]
        \item \textbf{Comparison of Adjustment Criteria:}\\ 
        $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g$ (Definition \ref{def:cac}) if and only if $\mb{S} \cup \mb{Z}$ satisfies the adjustment criterion relative to $(\mb{X}, \mb{Y})$ in $\g$ (Definition \ref{def:ac}, Supp.\ \ref{supp:defs}). \label{lem:comparison-a}

        \item \textbf{Comparison of Adjustment Sets:}\\
        $\mb{S}$ is a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g$ (Definition \ref{def:cas}) if and only if $\mb{S} \cup \mb{Z}$ is an adjustment set relative to $(\mb{X}, \mb{Y})$ in $\g$ (Definition \ref{def:as}, Supp.\ \ref{supp:defs}). \label{lem:comparison-b}
    \end{enumerate}

