\label{def:as}
{\normalfont (\textbf{Adjustment Set for MPDAGs (PAGs)}; \citealp{perkovic2017interpreting, perkovic2018complete, perkovic2015complete}; cf. \citealp{maathuis2015generalized})}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in a causal MPDAG (PAG) $\g$. Then $\mb{S}$ is an adjustment set relative to $(\mb{X},\mb{Y})$ in $\g$ if for any density $f$ consistent with $\g$
    \[ f(\mb{y}|do(\mb{x}))  = 
    \begin{cases} 
          f(\mb{y} | \mb{x}) & \mb{S}=\emptyset \\
          \int f(\mb{y} | \mb{x}, \mb{s}) f(\mb{s}) \mathop{}\!\mathrm{d} \mb{s}  & \mb{S}\neq\emptyset.
    \end{cases}
    \]

\[ f(\mb{y}|do(\mb{x}))  = 
    \begin{cases} 
          f(\mb{y} | \mb{x}) & \mb{S}=\emptyset \\
          \int f(\mb{y} | \mb{x}, \mb{s}) f(\mb{s}) \mathop{}\!\mathrm{d} \mb{s}  & \mb{S}\neq\emptyset.
    \end{cases}
    \]

\label{def:ac}
{\normalfont (\textbf{Adjustment Criterion for MPDAGs (PAGs)}; \citealp{perkovic2017interpreting, perkovic2018complete})}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in an MPDAG (PAG) $\g$, where every proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed (visible) edge out of $\mb{X}$. Then $\mb{S}$ satisfies the adjustment criterion relative to $(\mb{X},\mb{Y})$ in $\g$ if 
    \begin{enumerate}[label=\emph{(\alph*)}]
        \item $\mb{S} \cap \fb{\g} = \emptyset$, and
        \item $\mb{S}$ blocks all proper non-causal definite status paths from $\mb{X}$ to $\mb{Y}$ in $\g$. \label{def:ac-b}
    \end{enumerate}

\label{def:gbc}
{\normalfont (\textbf{Generalized Back-Door Criterion for DAGs}; cf. \citealp{maathuis2015generalized})}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in a DAG $\g[D]$. Then $\mb{S}$ satisfies the generalized back-door criterion relative to $(\mb{X},\mb{Y})$ in $\g[D]$ if 
    \begin{enumerate}[label=\emph{(\alph*)}]
        \item $\mb{S} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$, and
        \item $\mb{S} \cup \mb{X} \setminus \{X\}$ blocks all back-door paths from $X$ to $\mb{Y}$ in $\g[D]$, for every $X \in \mb{X}$.
    \end{enumerate}

\label{def:pbd}
{\normalfont (\textbf{Proper Back-Door Graph for DAGs}; cf. \citealp{perkovic2018complete})}
    Let $\mb{X}$ and $\mb{Y}$ be disjoint node sets in a DAG $\g[D]$. The proper back-door graph $\dpbd{\mb{XY}}$ is obtained from $\g[D]$ by removing all edges out of $\mb{X}$ that are on proper causal paths from $\mb{X}$ to $\mb{Y}$ in $\g[D]$.

\label{def:moral}
{\normalfont (\textbf{Moral Graph for DAGs}; cf. \citealp{lauritzen1988local}; cf. \citealp{perkovic2018complete})} 
    Let $\g[D]=(\mb{V},\mb{E})$ be a DAG. The moral graph $\g[D]^m$ is formed by adding the edge $A-B$ to any structure of the form $A \to C \gets B$ for any $A,B,C \in \mb{V}$, with $A \notin \mathrm{Adj}(B,\g[D])$ (marrying unmarried parents) and subsequently making all edges in the resulting graph undirected.

\label{def:distance}
{\normalfont (\textbf{Distance to $\mb{Z}$}; \citealp{zhang2006causal}; \citealp{perkovic2017interpreting})} 
    Let $\mb{X,Y}$ and $\mb{Z}$ be pairwise disjoint node sets in an MPDAG or PAG $\g$. Let $p$ be a path between $\mb{X}$ and $\mb{Y}$ in $\g$ such that every collider $C$ on $p$ has a possibly directed path (possibly of length $0$) to $\mb{Z}$. Define the \textit{distance to $\mb{Z}$} of $C$ to be the length of a shortest possibly directed path (possibly of length $0$) from $C$ to $\mb{Z}$, and define the \textit{distance to $\mb{Z}$} of $p$ to be the sum of the distances from $\mb{Z}$ of the colliders on $p$.

\begin{align}
        f(\mb{y} | do(\mb{x}),\mb{z,w}) = f(\mb{y} | do(\mb{x}),\mb{w}). \label{eq:rule1-do}
    \end{align}

\begin{align}
        f(\mb{y} | do(\mb{x}),\mb{z},do(\mb{w})) = f(\mb{y} | \mb{x},\mb{z},do(\mb{w})). \label{eq:rule2-do}
    \end{align}

\begin{align}
        \begin{split}
            f(\mb{y} | do(\mb{x}),\mb{z},do(\mb{w})) = f(\mb{y} | \mb{z},do(\mb{w})), \label{eq:rule3-do}
        \end{split}
    \end{align}

\label{lem:wright}
{\normalfont (Wright's Rule of \citealp{wright1921correlation})}
    Let $\mb{X}=\mb{AX}+\mb{\epsilon}$, where $\mb{Q} \in \mathbb{R}^{k \times k}$, $\mb{X} = (X_1, \dots, X_k)^T$ and $\mb{\epsilon} = (\epsilon_1, \dots, \epsilon_k)^T$ is a vector of mutually independent errors with means zero. Moreover, let $Var(\mb{X}) = \mb{I}$. Let $\g[D] = (\mb{X}, \mb{E})$, be the corresponding DAG such that $X_i \to X_j$ is in $\g[D]$ if and only if $A_{ji} \neq 0$. A non-zero entry $A_{ji}$ is called the edge coefficient of $X_i \to X_j$. For two distinct nodes $X_i$, $X_j \in \mb{X}$, let $p_1, \dots, p_r$ be all paths between $X_i$ and $X_j$ in $\g[D]$ that do not contain a collider. Then $\mathrm{Cov}(X_i, X_j) = \sum_{s=1}^r \pi_s$, where $\pi_s$ is the product of all edge coefficients along path $p_s$, $s \in \{1, \dots, r\}$.

\label{lem:mardia}
{\normalfont (Theorem 3.2.4 of \citealp{mardia1980multivariate})}
    Let $\mb{X} = (\mb{X_1}^T, \mb{X_2}^T)^T$ be a $p$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu} = (\mb{\mu_1}^T, \mb{\mu_2}^T)^T$ and covariance matrix $\mb{\Sigma} = \begin{bmatrix}
    \mb{\Sigma_{11}} & \mb{\Sigma}_{12} \\
    \mb{\Sigma_{21}} & \mb{\Sigma}_{22}
    \end{bmatrix}$, so that $\mb{X_1}$ is a $q$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu_1}$ and covariance matrix $\mb{\Sigma_{11}}$ and $\mb{X_2}$ is a $(p-q)$-dimensional multivariate Gaussian random vector with mean vector $\mb{\mu_2}$ and covariance matrix $\mb{\Sigma_{22}}$. Then $E[\mb{X_2}|\mb{X_1} = \mb{x_1}] = \mb{\mu_2} + \mb{\Sigma_{21}} \mb{\Sigma_{11}}^{-1}(\mb{x_1} - \mb{\mu_1})$.


\label{lem:markov-equiv}  
{\normalfont (cf. Theorem 1 and Proposition 3 of \citealp{lauritzen1990independence})}
    Let $\g[D] = (\mb{V},\mb{E})$ be a DAG, and let $f$ be an observational density over $\mb{V}$. Then $f$ is Markov compatible with $\g[D]$ if and only if 
    \begin{align*}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]) \cup \mathrm{Pa}(V_i,\g[D]) \big) \Big] | \mathrm{Pa}(V_i, \g[D])
    \end{align*}
    for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f$.

\begin{align*}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]) \cup \mathrm{Pa}(V_i,\g[D]) \big) \Big] | \mathrm{Pa}(V_i, \g[D])
    \end{align*}

\label{lem:equiv-z-mpdag} 
{\normalfont (cf. Lemma 3.2 of \citealp{perkovic2017interpreting})}
    Let $\mb{X}$ and $\mb{Z}$ be disjoint node sets in an MPDAG $\g$. If $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$, then $\mb{Z} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$ in every DAG $\g[D]$ in $[\g]$.

\label{lem:equiv-forb}
{\normalfont (Lemma C.2 of \citealp{perkovic2017interpreting}, Lemma 9 of \citealp{perkovic2018complete})}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in an MPDAG (PAG) $\g$, where every proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed (visible) edge out of $\mb{X}$. Then the following statements are equivalent.
    \begin{enumerate}[label = (\roman*)]
        \item $\mb{S} \cap \fb{\g} = \emptyset$.
        \item $\mb{S} \cap \fb{\g[D]} = \emptyset$ in every DAG (MAG) $\g[D]$ in $[\g]$.
    \end{enumerate}

\label{lem:equiv-block} 
{\normalfont (cf. Lemma C.3 of \citealp{perkovic2017interpreting}, Lemma 10 of \citealp{perkovic2018complete})}
    Let $\mb{X,Y}$ and $\mb{S}$ be pairwise disjoint node sets in an MPDAG (PAG) $\g$, where every proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a directed (visible) edge out of $\mb{X}$ and where $\mb{S} \cap \fb{\g} = \emptyset$. Then the following statements are equivalent.
    \begin{enumerate}[label = (\roman*)]
        \item $\mb{S}$ blocks all proper non-causal definite status paths from $\mb{X}$ to $\mb{Y}$ in $\g$.
        \item $\mb{S}$ blocks all proper non-causal definite status paths from $\mb{X}$ to $\mb{Y}$ in $\g[D]$ for every DAG (MAG) $\g[D]$ in $[\g]$.
    \end{enumerate}

\label{thm:richardson}
{\normalfont (cf. Proposition 3 of \cite{lauritzen1990independence}, cf. Corollary 2 of \cite{richardson2003markov})}
    Let $\mb{X},\mb{Y}$, and $\mb{Z}$ be pairwise disjoint node sets in a DAG $\g[D]$. Further let $(\g[D]_{\mathrm{An}(\mb{X} \cup \mb{Y} \cup \mb{Z},\g[D])})^m$ be the moral induced subgraph of $\g[D]$ on nodes $\mathrm{An}(\mb{X} \cup \mb{Y} \cup \mb{Z},\g[D])$ (see Definition \ref{def:moral}). Then $\mb{Z}$ d-separates $\mb{X}$ and $\mb{Y}$ in $\g[D]$ if and only if all paths between $\mb{X}$ and $\mb{Y}$ in $(\g[D]_{\mathrm{An}(\mb{X} \cup \mb{Y} \cup \mb{Z},\g[D])})^m$ contain at least one node in $\mb{Z}$.

\label{thm:ac-alt}
{\normalfont (cf. Theorem 7 of \citealp{perkovic2018complete})}
    Consider the definition of the adjustment criterion for MPDAGs (Definition \ref{def:ac}) in the specific setting of a DAG. In this setting, replacing condition \ref{def:ac-b} in Definition \ref{def:ac} with
    \begin{enumerate}[label=\emph{(\alph*)}]
        \setcounter{enumi}{1}
        \item $\mb{S}$ d-separates $\mb{X}$ and $\mb{Y}$ in $\dpbd{\mb{XY}}$ (see Definition \ref{def:pbd})
    \end{enumerate}
    results in a criterion that is equivalent to Definition \ref{def:ac} applied to a DAG.

\label{thm:gbc-as}
{\normalfont (cf. Theorem 3.1 of \citealp{maathuis2015generalized})}
    Let $\mb{X},\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in a causal DAG $\g[D]$. If $\mb{S}$ satisfies the generalized back-door criterion relative to $(\mb{X},\mb{Y})$ in $\g[D]$ (Definition \ref{def:gbc}), then $\mb{S}$ is an adjustment set relative to $(\mb{X},\mb{Y})$ in $\g[D]$ (Definition \ref{def:as}).

\label{lem:henckel-e6}
{\normalfont (cf. Lemma E.6 of \citealp{henckel2022graphical})}
    Let $\mb{X},\mb{Y}$ be disjoint node sets in an MPDAG $\g$. If there is no proper possibly causal path from $\mb{X}$ to $\mb{Y}$ that starts with an undirected edge in $\g$, then $\fb{\g} \subseteq \mathrm{De}(\mb{X}, \g)$.

\label{lem:perkovic17-35}
{\normalfont (cf. Lemma 3.5 of \citealp{perkovic2017interpreting})}
    Let $p = \langle V_1, \dots, V_k \rangle, k > 1$, be a definite status path in MPDAG $\g$. Then p is a possibly causal path in $\g$ if and only if there is no edge $V_i \leftarrow V_{i+1}$, $i \in \{1, \dots, k-1\}$ in $\g$.

\label{lem:basic-property-pags}
{\normalfont (cf. Lemma 3.3.1 of \citealp{zhang2006causal})}
    Let $X$, $Y$, and $Z$ be distinct nodes in a PAG $\g$. If $X \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(0.2,0){$\bullet$} \put(1,0){$\rightarrow$} \end{picture} Y \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(1,1){\circle{1}} \put(1.5,1){\line(1,0){2.4}} \put(2.9,0){$\bullet$} \end{picture} Z$, then there is an edge between $X$ and $Z$ with an arrowhead at $Z$. Furthermore, if the edge between $X$ and $Y$ is $X \rightarrow Y$, then the edge between $X$ and $Z$ is either $X \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(1,1){\circle{1}} \put(1.2,0){$\rightarrow$} \end{picture} Z$ or $X \rightarrow Z$ (that is, not $X \leftrightarrow Z$).

\label{lem:marl-cycle}
{\normalfont (cf. Lemma 7.5 of \citealp{maathuis2015generalized})}
    Let $X$ and $Y$ be two distinct nodes in a  MAG or PAG $\g$. Then $\g$ cannot have  both an edge $Y \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(0.2,0){$\bullet$} \put(1,0){$\rightarrow$} \end{picture} X$ and a path $\langle X = V_1,\dots, V_k = Y \rangle, k>2$ where each edge $\langle V_i, V_{i+1} \rangle, i \in \{1, \dots, k-1\}$, is of one of these forms: $V_i \to V_{i+1}$ or $V_{i} \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(1,1){\circle{1}} \put(1.5,1){\line(1,0){2.4}} \put(2.9,0){$\bullet$} \end{picture} V_{i+1}$.

\label{lem:richprime2}
{\normalfont (cf. Lemma 17 of \citealp{perkovic2018complete})}
    Let $\mb{X,Y, Z}$ and $\mb{S}$ be pairwise disjoint node sets in a MAG or PAG $\g$. Suppose  that every proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g$ starts with a visible edge out of $\mb{X}$ and that $\big[\mb{S} \cup \mb{Z} \big] \cap \fb{\g} = \emptyset$. Suppose furthermore that there is a path $p$ from $\mb{X}$ to $\mb{Y}$ in $\g$ such that
    \begin{enumerate}[label=(\roman*)]
        \item $p$ is a proper definite status non-causal path from $\mb{X}$ to $\mb{Y}$ in $\g$,
        \item all colliders on $p$ are in $\mathrm{An}(\mb{X} \cup \mb{Y} \cup \mb{Z} \cup \mb{S}, \g) \setminus \big[ \mb{X} \cup \mb{Y} \cup \fb{\g}\big]$, and
        \item no definite non-collider on $p$ is in $\mb{S} \cup \mb{Z}$.
    \end{enumerate}
    Then there is a proper definite status non-causal path from $\mb{X}$ to $\mb{Y}$ that is m-connecting given $\mb{S} \cup \mb{Z}$ in $\g$.

\label{thm:ac-as}
{\normalfont (cf. Theorem 4.4 of \citealp{perkovic2017interpreting}, Theorems 5 and 56 of \citealp{perkovic2018complete})}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{S}$ be pairwise disjoint node sets in a causal MPDAG (PAG) $\g$. Then $\mb{S}$ is an adjustment set relative to $(\mb{X,Y})$ in $\g$ (Definition \ref{def:as}) if and only if $\mb{S}$ satisfies the adjustment criterion relative to $(\mb{X,Y})$ in $\g$ (Definition \ref{def:ac}).


\label{lem:adding-edges-imply}
{\normalfont (cf. Lemma F.1 of \citealp{rothenhausler2018causal})}
    Let $X$ and $Y$ be nodes in an MPDAG $\g = (\mb{V,E})$ such that $X - Y$ is in $\g$. Let $\g'$ be an MPDAG constructed from $\g$ by adding $X \to Y$ and completing the orientation rules R1 - R4 of \cite{meek1995causal}. For any $Z,W \in \mb{V}$, if $Z - W$ is in $\g$ and $Z \rightarrow W$ is in $\g'$, then $W \in \mathrm{De}(Y,\g')$.

\label{lem:undirected-imply}
{\normalfont (cf. Lemma F.2 of \citealp{rothenhausler2018causal})}
    Let $X$ be a node in an MPDAG $\g=(\mb{V}, \mb{E})$, and let $\mb{S}$ be a set such that for all $S \in \mb{S}$, $X - S$ is in $\g$. Then there is an MPDAG $\g' = (\mb{V}, \mb{E'})$ that is formed by taking $\g$, orienting $X \to S$ for all $S \in \mb{S}$, and completing R1-R4 of \cite{meek1995causal}.


\label{lem:sound-setup1-perk}
{\normalfont (cf. Lemma 59 of \citealp{perkovic2018complete})}
    Let $\mb{X},\mb{Y}$ and $\mb{S}$ be pairwise disjoint node sets in a DAG $\g[D]$ such that $\mb{S}$ satisfies the adjustment criterion relative to $(\mb{X,Y})$ in $\g[D]$ (Definition \ref{def:ac}). Let $\mb{J} \subseteq \mathrm{An}(\mb{X} \cup \mb{Y},\g[D]) \setminus (\mathrm{De}(\mb{X}, \g[D]) \cup \mb{Y})$ and $\mb{\tilde{S}} = \mb{S} \cup \mb{J}$. Then the following statements hold:
    \begin{enumerate}[label = (\roman*)]
        \item $\mb{\tilde{S}}$ satisfies the adjustment criterion relative to $(\mb{X,Y})$ in $\g[D]$, and
        \item $\int_\mb{s} f(\mb{y} \mid \mb{x,s})f(\mb{s}) d\mb{s} = \int_{\mb{\tilde{s}}} f(\mb{y} \mid \mb{x,\tilde{s}}) f(\mb{\tilde{s}}) d\mb{\tilde{s}}$, for any density $f$ consistent with $\g[D]$.
    \end{enumerate}

This lemma extends Proposition 3.2 of \cite{perkovic2020identifying} and its proof follows similar logic to that of \cite{perkovic2020identifying}.

Suppose that there is a proper possibly causal path from $\mb{X}$ to $\mb{Y}$ in $\g = (\mb{V},\mb{E})$  that starts with an undirected edge and does not contain any element of $\mb{Z}$. Then by Lemma \ref{lem:twopaths-corrollary}, there is one such path -- call it $q=\langle X=V_0, \dots, V_k=Y\rangle$, $X \in \mb{X}$, $Y \in \mb{Y}, k \ge 1$ -- where the corresponding paths in two DAGs in $[\g]$ take the forms $X \to \dots \to Y$ and $X \gets V_1 \to \dots \to Y$ ($X \gets Y$ when $k=1$). Call these DAGs $\g[D]^1$ and $\g[D]^2$ with paths $q_1$ and $q_2$, respectively.

To prove that the conditional causal effect of $\mb{X}$ on $\mb{Y}$ given $\mb{Z}$ is not identifiable in $\g$, it suffices to show that there are two families of interventional densities over $\mb{V}$ -- call them $\mb{F^*_1}$ and $\mb{F^*_2}$, where for $i \in \{1,2\}$, we define $\mb{F^*_i} = \{ f_i(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ -- such that the following properties hold. 
\begin{enumerate}[label=(\roman*)]
    \item $\g[D]^1$ and $\g[D]^2$ are compatible with $\mb{F^*_1}$ and $\mb{F^*_2}$, respectively.
        \footnote{For brevity, we say a DAG is ``compatible with'' a set of interventional densities and an interventional density is ``consistent with'' a DAG as shorthand for these claims holding only were the DAG to be causal.}
        \label{prop:id-necessary-1}
    \item $f_1(\mb{v}) = f_2(\mb{v})$. \label{prop:id-necessary-2}
    \item $f_1(\mb{y} | do(\mb{x}), \mb{z}) \neq f_2(\mb{y} | do(\mb{x}), \mb{z})$. \label{prop:id-necessary-3}
\end{enumerate}

To define such families, we start by introducing an additional DAG and an observational density $f(\mb{v})$. That is, let $\g[D]^{1'}$ be a DAG constructed by removing every edge from $\g[D]^1$ except for the edges on $q_1$. Then let $f(\mb{v})$ be the multivariate normal distribution under the following linear structural equation model (SEM). Each random variable $A \in \mb{V}$ has mean zero and is a linear combination of its parents in $\g[D]^{1'}$ and $\epsilon_{A} \sim N(0, \sigma^2_A)$, where $\{\mb{\epsilon}_{A}: A \in \mb{V}\}$ are mutually independent. The coefficients in this linear combination are defined by the edge coefficients of $\g[D]^{1'}$. We pick these edge coefficients in conjunction with $\{\mb{\sigma}^2_{A}: A \in \mb{V}\}$ in such a way that each coefficient is in $(0,1)$ and $\mathrm{Var}(A) = 1$ for all $A \in \mb{V}$.

From this, we define $\mb{F^*_1} = \{ f_1(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that $\g[D]^{1'}$ is compatible with $\mb{F^*_1}$ and such that $f_1(\mb{v}) = f(\mb{v})$. Note that $f(\mb{v})$ is Markov compatible with $\g[D]^{1'}$ by construction, and we build the interventional densities in $\mb{F^*_1}$ by replacing the intervening random variables in the SEM with their interventional values \citep{pearl2009causality}.

To construct the second family of interventional densities, we introduce the DAG $\g[D]^{2'}$, which we form by removing every edge from $\g[D]^2$ except for the edges on $q_2$. Then note that we could have defined $f(\mb{v})$ using a linear SEM based on the parents in $\g[D]^{2'}$. In this case, the resulting observational density would again be a multivariate normal with mean vector zero and a covariance matrix with ones on the diagonal. The off-diagonal entries would be the covariances between the variables in $\g[D]^{2'}$. But note that by Lemma \ref{lem:wright}, these values will equal the product of all edge coefficients between the relevant nodes in $\g[D]^{2'}$. Since $\g[D]^{1'}$ and $\g[D]^{2'}$ contain no paths with colliders, the observational density $f(\mb{v})$ built using $\g[D]^{2'}$ will be an identical distribution to that built under $\g[D]^{1'}$. Thus, in an analogous way to $\mb{F^*_1}$, we define $\mb{F^*_2} = \{ f_1(\mb{v}|do(\mb{x'})) : \mb{X'} \subseteq \mb{V} \}$ such that $\g[D]^{2'}$ is compatible with $\mb{F^*_2}$ and such that $f_2(\mb{v}) = f(\mb{v})$.

Having defined $\mb{F^*_1}$ and $\mb{F^*_2}$, we check that their desired properties hold. Note that by construction, $\g[D]^{1'}$ and $\g[D]^{2'}$ are compatible with $\mb{F^*_1}$ and $\mb{F^*_2}$, respectively. Thus \ref{prop:id-necessary-1} holds by Lemma \ref{lem:markov-sub}. Similarly by construction, \ref{prop:id-necessary-2} holds. To show that \ref{prop:id-necessary-3} holds, it suffices to show that $E[Y | do(\mb{X}=\mb{1}), \mb{Z}]$ is not the same under $f_1$ and $f_2$. 

To calculate these expectations, we first want to apply Rules 1-3 of the do calculus (Equations \eqref{eq:rule1-do}-\eqref{eq:rule3-do}). Since $f_i(\mb{v} | do(\mb{x}))$, $i \in \{1,2\}$, is consistent with $\g[D]^{i'}$, we apply these rules using graphical relationships in $\g[D]^{i'}$. Because the path in $\g[D]^{i'}$ corresponding to $q_i$, $i \in \{1,2\}$, does not contain nodes in $\mb{Z}$ or $\mb{X} \setminus \{X\}$, then $Y \perp_{d} \mb{Z} | \mb{X}$ and $Y \perp_{d} \mb{X} \setminus \{X\} | X$ in $\g[D]^{i'}_{\overline{\mb{X}}}$. Further, $Y \perp_{d} X$ in $\g[D]^{1'}_{\underline{X}}$ and $Y \perp_{d} X$ in $\g[D]^{2'}_{\overline{X}}$. Thus by Rules 1-3 of the do calculus (Equations \eqref{eq:rule1-do}-\eqref{eq:rule3-do}), the following hold.
\begin{align*}
    E_1[Y | do(\mb{X}=\mb{1}), \mb{Z}] &= E_1[Y | do(X=1)] = E_1[Y|X=1] := a.\\
    E_2[Y | do(\mb{X}=\mb{1}), \mb{Z}] &= E_2[Y | do(X=1)] = E_2[Y] := b,
\end{align*}    
where $E_i, i \in \{1,2\}$ is the expectation under $f_i$. To calculate $a$ and $b$, we rely on the observational density $f(\mb{v})$, which was constructed using $\g[D]^{1'}$. By Lemma \ref{lem:mardia}, $a$ equals the covariance of $X$ and $Y$ under $f(\mb{v})$, and by Lemma \ref{lem:wright}, $\mathrm{Cov}(X,Y)$ equals the product of all edge coefficients in $\g[D]^{1'}$, which were chosen to be in $(0,1)$. Therefore, $a \neq 0$. But by definition of $f(\mb{v})$, $b=0$.

Suppose that $f(\mb{v} | do(\mb{x}))$ is consistent with $\g[D]^*$. Then by definition, there exists a set of interventional densities $\mb{F^*}$ such that $\g[D]^*$ is compatible with $\mb{F^*}$. Let $f(\mb{v})$ be the density in $\mb{F^*}$ under a null intervention. Note that by the truncated factorization in Equation \eqref{eq:trunc-fact}, $f(\mb{v})$ is Markov compatible with $\g[D]^*$. Thus by Lemma \ref{lem:markov-equiv},
\begin{align}
    V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]^*) \cup \mathrm{Pa}(V_i,\g[D]^*) \big) \Big] | \mathrm{Pa}(V_i, \g[D]^*) \label{eq:markov-sub-1}
\end{align}
for all $V_i \in \mb{V}$, where $\perp\!\!\!\!\perp$ indicates independence with respect to $f(\mb{v})$. Further, since $\mathrm{De}(V_i,\g[D]^*) \subseteq \mathrm{De}(V_i,\g[D])$, then $\mathrm{De}(V_i,\g[D]^*) \cap \mathrm{Pa}(V_i,\g[D]) = \emptyset$ and thus $\mathrm{Pa}(V_i,\g[D]) \subseteq \mb{V} \setminus \mathrm{De}(V_i, \g[D]^*)$. Therefore it follows from \eqref{eq:markov-sub-1} that
\begin{align} 
    V_i \perp\!\!\!\!\perp \Big[ \mathrm{Pa}(V_i,\g[D]) \setminus \mathrm{Pa}(V_i,\g[D]^*) \Big] \,\, \Big| \,\, \mathrm{Pa}(V_i,\g[D]^*). \label{eq:markov-sub-2}
\end{align}

Let $f(\mb{v} | do(\mb{x'}))$, $\mb{X'} \subseteq \mb{V}$, be an arbitrary density in $\mb{F^*}$. Then by definition and \eqref{eq:markov-sub-2}
\begin{align*}
    f(\mb{v} | do(\mb{x'})) &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D]^*)) \mathds{1}(\mb{X'} = \mb{x'})\\
                            &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D])) \mathds{1}(\mb{X'} = \mb{x'}).
\end{align*}
Since $f(\mb{v} | do(\mb{x'}))$ was arbitrary, this holds for all densities in $\mb{F^*}$. Thus, $\g[D]$ is compatible with $\mb{F^*}$. Since $f(\mb{v} | do(\mb{x})) \in \mb{F^*}$, then by definition, it is consistent with $\g[D]$.

\begin{align}
        V_i \perp\!\!\!\!\perp \Big[ \mb{V} \setminus \big( \mathrm{De}(V_i, \g[D]^*) \cup \mathrm{Pa}(V_i,\g[D]^*) \big) \Big] | \mathrm{Pa}(V_i, \g[D]^*) \label{eq:markov-sub-1}
    \end{align}

\begin{align} 
        V_i \perp\!\!\!\!\perp \Big[ \mathrm{Pa}(V_i,\g[D]) \setminus \mathrm{Pa}(V_i,\g[D]^*) \Big] \,\, \Big| \,\, \mathrm{Pa}(V_i,\g[D]^*). \label{eq:markov-sub-2}
    \end{align}

\begin{align*}
        f(\mb{v} | do(\mb{x'})) &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D]^*)) \mathds{1}(\mb{X'} = \mb{x'})\\
                                &= \prod_{V_i \in \mb{V} \setminus \mb{X'}} f(v_i|\mathrm{pa}(v_i,\g[D])) \mathds{1}(\mb{X'} = \mb{x'}).
    \end{align*}

\label{thm:completeness}
{\normalfont (\textbf{Completeness of the Conditional Adjustment Criterion for DAGs})}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a causal DAG $\g[D]$, where $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$. If $\mb{S}$ is a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g[D]$ (Definition \ref{def:cas}), then $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$ (Definition \ref{def:cac}).

\label{thm:soundness}
{\normalfont (\textbf{Soundness of the Conditional Adjustment Criterion for DAGs})}
    Let $\mb{X,Y,Z}$, and $\mb{S}$ be pairwise disjoint node sets in a causal DAG $\g[D]$, where $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$. If $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y, Z})$ in $\g[D]$ (Definition \ref{def:cac}), then $\mb{S}$ is a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g[D]$ (Definition \ref{def:cas}).


This theorem is analogous to Theorem 58 of \cite{perkovic2018complete} for the adjustment criterion. We use the same proof strategy and adapt the arguments to suit our needs.

Suppose that $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$ and let $f$ be a density consistent with $\g[D]$. Our goal is to prove that
\begin{equation}
    {f(\mb{y} | do(\mb{x}), \mb{z}) = \int_{\mb{s}} f(\mb{y} | \mb{x,z,s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}.}
\end{equation}

We consider three cases below. Before this, we prove an equality that holds in all cases. Let $\mb{Y_D} = \mb{Y} \cap \mathrm{De}(\mb{X},\g[D])$ and $\mb{Y_N} = \mb{Y} \setminus \mathrm{De}(\mb{X}, \g[D])$. Then $\mb{Y_N} \perp_{d} \mb{X} \given \mb{Z}$ in $\g[D]_{\overline{\mb{X}}}$, since $\g[D]_{\overline{\mb{X}}}$ does not contain edges into $\mb{X}$ and since all paths from $\mb{X}$ to $\mb{Y_N}$ that start with an edge out of $\mb{X}$ in $\g[D]_{\overline{\mb{X}}}$ contain a collider -- a collider that cannot be an element of $\mathrm{An}(\mb{Z},\g[D])$ since $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$. Rule 3 of the do calculus (Equation \eqref{eq:rule3-do}) then implies
\begin{align}
    {f(\mb{y_N} | do(\mb{x}), \mb{z}) = f(\mb{y_N} | \mb{z}).} \label{eq:soundness-1}
\end{align}



\textbf{Case 1:} Assume that $\mb{Y_D} = \emptyset$ so that $\mb{Y} = \mb{Y_N}$. Then we have the following. (Justification for the numbered equations is below.)
\begin{align}
    f(\mb{y} | do(\mb{x}) , \mb{z})
        &= f(\mb{y} | \mb{z}) \label{eq:soundness-2}\\
        &= \int_{\mb{s}} f(\mb{y} | \mb{z, s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
        &= \int_{\mb{s}} f(\mb{y} | \mb{x, z, s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}. \label{eq:soundness-3}
\end{align}
Equation \eqref{eq:soundness-2} follows from Equation \eqref{eq:soundness-1} and $\mb{Y} = \mb{Y_N}$. Equation \eqref{eq:soundness-3} follows from the following logic. Since $\mb{S}$ satisfies the conditional adjustment criterion relative to ($\mb{X,Y,Z}$) in $\g[D]$ and since $\mb{Y} = \mb{Y_N}$, it holds that $\mb{S} \cup \mb{Z}$ blocks all paths from $\mb{X}$ to $\mb{Y}$ in $\g[D]$. Thus, $\mb{X} \perp_{d} \mb{Y} \given \mb{S} \cup \mb{Z}$ in $\g[D]$, which implies the analogous independence statement.



\textbf{Case 2:} Assume $\mb{Y_N} = \emptyset$ so that $\mb{Y} = \mb{Y_D}$. Define $\mb{H} = \mathrm{An}(\mb{X} \cup \mb{Y},\g[D]) \setminus (\mathrm{De}(\mb{X}, \g[D]) \cup \mb{Y} \cup \mb{Z})$, $\mb{\tilde{S}} = \mb{S} \cup \mb{H}$, $\mb{\tilde{S}_D} = \mb{\tilde{S}} \cap \mathrm{De}(\mb{X}, \g[D])$, and $\mb{\tilde{S}_N} = \mb{\tilde{S}} \setminus \mathrm{De}(\mb{X}, \g[D])$. Then we have the following. (Justification for the numbered equations is below.)
\begin{align}
    f(\mb{y} | do(\mb{x}), \mb{z})
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) f(\mb{\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-4} \\
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) \int_{\mb{\tilde{s}_D}} f(\mb{\tilde{s}_D,\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
        &= \int_{\mb{\tilde{s}_D,\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) f(\mb{\tilde{s}_D,\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-5} \\
        &= \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}} \label{eq:soundness-6} \\
        &= \int_{\mb{s}} f(\mb{y} | \mb{x,z,s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}. \label{eq:soundness-7}
\end{align}
Equation \eqref{eq:soundness-4} holds since by Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-4}, $\mb{\tilde{S}_N}$ is a conditional adjustment set relative to $(\mb{X,Y,Z})$ in $\g[D]$. Equation \eqref{eq:soundness-5} holds since $\mb{\tilde{S}_D}$ is disjoint from $\mb{Y} \cup \mb{X} \cup \mb{\tilde{S}_N} \cup \mb{Z}$. Equation \eqref{eq:soundness-6} holds since by Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-3}, we have $\mb{Y} \perp_{d} \mb{\tilde{S}_D} \given \mb{X} \cup \mb{\tilde{S}_N} \cup \mb{Z}$ in $\g[D]$, where the analogous independence statement follows. Finally, Equation \eqref{eq:soundness-7} results from applying Lemma \ref{lem:sound-setup1}\ref{lem:sound-setup1-b}.



\textbf{Case 3:} Assume $\mb{Y_D} \neq \emptyset$ and $\mb{Y_N} \neq \emptyset$ and define $\mb{H}, \mb{\tilde{S}}, \mb{\tilde{S}_D}$, and $\mb{\tilde{S}_N}$ as in Case 2 above. We start by showing two equalities that rely on the do calculus. First note that by Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-6}, $\mb{Y_D} \perp_{d} \mb{Y_N} \cup \mb{\tilde{S}_N} \cup \mb{Z} \given \mb{X}$ in $\g[D]_{\overline{\mb{X}}\underline{\mb{Y_N} \cup \mb{\tilde{S}_N} \cup \mb{Z}}}$. Thus by Rule 2 of the do calculus (Equation \eqref{eq:rule2-do}), we have that 
\begin{align}
    {f(\mb{y_D} | do(\mb{x}),\mb{y_N, z,\tilde{s}_N}) = f(\mb{y_D} | do(\mb{x,y_N,z,\tilde{s}_N})).} \label{eq:soundness-8}
\end{align}
Second, note by Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-7}, $\mb{\tilde{S}_N} \perp_{d} \mb{X} \given \mb{Y_N} \cup \mb{Z}$ in $\g[D]_{\overline{\mb{X}}}$. Thus by Rule 3 of the do calculus (Equation \eqref{eq:rule3-do}), we have that
\begin{align}
    {f(\mb{\tilde{s}_N} | do(\mb{x}),\mb{y_N,z}) = f(\mb{\tilde{s}_N} | \mb{y_N,z}).} \label{eq:soundness-9}
\end{align}
Then we have the following. (Justification for the numbered equations is below.)
\begin{align}
    f(\mb{y} | do(\mb{x}), \mb{z})
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y,\tilde{s}_N} | do(\mb{x}), \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y_D} | \mb{\tilde{s}_N,y_N}, do(\mb{x}), \mb{z}) f(\mb{\tilde{s}_N} | \mb{y_N}, do(\mb{x}), \mb{z}) f(\mb{y_N} | do(\mb{x}), \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y_D} | do(\mb{x,y_N,z,\tilde{s}_N})) f(\mb{\tilde{s}_N} | \mb{y_N, z}) f(\mb{y_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-10} \\

        &= \int_{\mb{\tilde{s}_N}} f(\mb{y_D} | do(\mb{x,y_N,z,\tilde{s}_N})) \int_{\mb{\tilde{s}_D}} f(\mb{\tilde{s}_N,y_N,\tilde{s}_D} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y_D} | do(\mb{x,y_N,z,\tilde{s}_N})) \int_{\mb{\tilde{s}_D}} f(\mb{y_N} | \mb{\tilde{s},z}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
        &= \int_{\mb{\tilde{s}_N}} f(\mb{y_D} | \mb{y_N,x,z,\tilde{s}_N}) \int_{\mb{\tilde{s}_D}} f(\mb{y_N} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-11} \\

        &= \int_{\mb{\tilde{s}}} f(\mb{y_D} | \mb{y_N,x,z,\tilde{s}}) f(\mb{y_N} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}} \label{eq:soundness-12} \\
        &= \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}} \nonumber \\
        &= \int_{\mb{s}} f(\mb{y} | \mb{x,z,}\mb{s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}. \label{eq:soundness-13}
\end{align}
Equation \eqref{eq:soundness-10} holds by the applying Equations \eqref{eq:soundness-8}, \eqref{eq:soundness-9}, and \eqref{eq:soundness-1}. Equation \eqref{eq:soundness-11} holds by the following logic. By Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-5}, the empty set is an adjustment set relative to $(\mb{X} \cup \mb{Y_N} \cup \mb{\tilde{S}_N} \cup \mb{Z}, \mb{Y_D})$ in $\g[D]$. Then by Lemma \ref{lem:sound-setup1}\ref{lem:sound-setup1-a}, $\mb{\tilde{S}}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$, and so $\mb{\tilde{S}} \cup \mb{Z}$ blocks all paths from $\mb{X}$ to $\mb{Y_N}$ in $\g[D]$. Thus, $\mb{Y_N} \perp_{d} \mb{X} \given \mb{\tilde{S}} \cup \mb{Z}$ in $\g[D]$, where the analogous independence statement follows.

Equation \eqref{eq:soundness-12} holds since $\mb{\tilde{S}_D}$ is disjoint from $\mb{Y} \cup \mb{X} \cup \mb{\tilde{S}_N} \cup \mb{Z}$ and since by Lemma \ref{lem:sound-setup2}\ref{lem:sound-setup2-3}, we have that $\mb{Y_D} \perp_{d} \mb{\tilde{S}_D} \given \mb{Y_N} \cup \mb{X} \cup \mb{\tilde{S}_N} \cup \mb{Z}$ in $\g[D]$, where the analogous independence statement follows. Finally, Equation \eqref{eq:soundness-13} results from applying Lemma \ref{lem:sound-setup1}\ref{lem:sound-setup1-b}.

\begin{equation}
        {f(\mb{y} | do(\mb{x}), \mb{z}) = \int_{\mb{s}} f(\mb{y} | \mb{x,z,s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}.}
    \end{equation}

\begin{align}
        {f(\mb{y_N} | do(\mb{x}), \mb{z}) = f(\mb{y_N} | \mb{z}).} \label{eq:soundness-1}
    \end{align}

\begin{align}
        f(\mb{y} | do(\mb{x}) , \mb{z})
            &= f(\mb{y} | \mb{z}) \label{eq:soundness-2}\\
            &= \int_{\mb{s}} f(\mb{y} | \mb{z, s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
            &= \int_{\mb{s}} f(\mb{y} | \mb{x, z, s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}. \label{eq:soundness-3}
    \end{align}

\begin{align}
        f(\mb{y} | do(\mb{x}), \mb{z})
            &= \int_{\mb{\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) f(\mb{\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-4} \\
            &= \int_{\mb{\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) \int_{\mb{\tilde{s}_D}} f(\mb{\tilde{s}_D,\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \nonumber \\
            &= \int_{\mb{\tilde{s}_D,\tilde{s}_N}} f(\mb{y} | \mb{x,z,\tilde{s}_N}) f(\mb{\tilde{s}_D,\tilde{s}_N} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}_D} \mathop{}\!\mathrm{d} \mb{\tilde{s}_N} \label{eq:soundness-5} \\
            &= \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}} \label{eq:soundness-6} \\
            &= \int_{\mb{s}} f(\mb{y} | \mb{x,z,s}) f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s}. \label{eq:soundness-7}
    \end{align}

\begin{align}
        {f(\mb{y_D} | do(\mb{x}),\mb{y_N, z,\tilde{s}_N}) = f(\mb{y_D} | do(\mb{x,y_N,z,\tilde{s}_N})).} \label{eq:soundness-8}
    \end{align}

\begin{align}
        {f(\mb{\tilde{s}_N} | do(\mb{x}),\mb{y_N,z}) = f(\mb{\tilde{s}_N} | \mb{y_N,z}).} \label{eq:soundness-9}
    \end{align}

\label{lem:sound-setup1}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a causal DAG $\g[D]$, where $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$ and where $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$ (Definition \ref{def:cac}). Let $\mb{H} \subseteq \mathrm{An}(\mb{X} \cup \mb{Y},\g[D]) \setminus (\mathrm{De}(\mb{X}, \g[D]) \cup \mb{Y} \cup \mb{Z})$ and $\mb{\tilde{S}} = \mb{S} \cup \mb{H}$. Then:
    \begin{enumerate}[label = (\roman*)]
        \item \label{lem:sound-setup1-a} $\mb{\tilde{S}}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$, and
        \item \label{lem:sound-setup1-b} $\int_\mb{s} f(\mb{y} | \mb{x,z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} = \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z})  \mathop{}\!\mathrm{d} \mb{\tilde{s}}$, for any density $f$ consistent with $\g[D]$.
    \end{enumerate}


This lemma is analogous to Lemma 59 of \cite{perkovic2018complete} (Lemma \ref{lem:sound-setup1-perk}). We use the same proof strategy and adapt the arguments to suit our needs.

\ref{lem:sound-setup1-a} 
By Lemma \ref{lem:comparison}\ref{lem:comparison-a}, since $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$, then $\mb{S} \cup \mb{Z}$ satisfies the adjustment criterion relative to $(\mb{X}, \mb{Y})$ in $\g[D]$. Then by Lemma \ref{lem:sound-setup1-perk}, $\mb{\tilde{S}} \cup \mb{Z}$ satisfies the adjustment criterion relative to $(\mb{X}, \mb{Y})$. The statement follows by a second use of Lemma \ref{lem:comparison}\ref{lem:comparison-a}.

\ref{lem:sound-setup1-b} Let $f$ be an arbitrary density consistent with $\g[D]$. We proceed with a proof by induction.





\textbf{Base case:} Suppose $\mb{H} = \{H\}$ so that $|\mb{H}|=1$. When $H \in \mb{S}$, the claim clearly holds. Thus, we let $H \notin \mb{S}$. Note that the claim holds if either $\mb{Y} \perp_{d} H \given \mb{X} \cup \mb{S} \cup \mb{Z}$ or $\mb{X} \perp_{d} H \given \mb{S} \cup \mb{Z}$ in $\g[D]$. To see this, we calculate the following.    
\begin{enumerate}[label=\emph{(\alph*)}]
    \item \label{pf:sound-setup1-a}
    When $(\mb{Y} \perp_{d} H \given \mb{X} \cup \mb{S} \cup \mb{Z})_{\g[D]}$, then
    \begin{align}
        \int_\mb{s} f(\mb{y} | \mb{x,z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} 
            &= \int_\mb{s} f(\mb{y} | \mb{x,z,s})\int_{h}f(\mb{s},h | \mb{z}) \mathop{}\!\mathrm{d} h \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
            &= \int_{\mb{s},h} f(\mb{y} | \mb{x,z,s}) f(\mb{s},h | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \mathop{}\!\mathrm{d} h  \nonumber \\
            &= \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}})f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}}, \nonumber 
    \end{align}
    where the second equality holds since $H \notin \mb{Y} \cup \mb{X} \cup \mb{S} \cup \mb{Z}$.

    \item \label{pf:sound-setup1-b}
    When $(\mb{X} \perp_{d} H \given \mb{S} \cup \mb{Z})_{\g[D]}$, then 
    \begin{align}
        \int_\mb{s} f(\mb{y} | \mb{x,z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} 
            &= \int_{\mb{s}}f(\mb{s} | \mb{z})\int_{h} f(\mb{y},h | \mb{x,z,s}) \mathop{}\!\mathrm{d} h \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
            &= \int_{\mb{s},h} f(\mb{y},h | \mb{x,z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \mathop{}\!\mathrm{d} h \nonumber \\
            &= \int_{\mb{s},h} f(\mb{y} | \mb{x,z,s},h)f(h | \mb{x,z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \mathop{}\!\mathrm{d} h \nonumber \\
            &= \int_{\mb{s},h} f(\mb{y} | \mb{x,z,s},h)f(h | \mb{z,s})f(\mb{s} | \mb{z}) \mathop{}\!\mathrm{d} \mb{s} \mathop{}\!\mathrm{d} h \nonumber \\
            &= \int_{\mb{\tilde{s}}} f(\mb{y} | \mb{x,z,\tilde{s}}) f(\mb{\tilde{s}} | \mb{z}) \mathop{}\!\mathrm{d} \mb{\tilde{s}}, \nonumber 
    \end{align}
    where the second equality holds since $H \notin \mb{S} \cup \mb{Z}$.
\end{enumerate}

We use the remainder of the base case to show that \ref{pf:sound-setup1-a} or \ref{pf:sound-setup1-b} must hold. For sake of contradiction, suppose that neither hold. This implies that there are two paths in $\g[D]$: one from $\mb{X}$ to $H$ that is d-connecting given $\mb{S} \cup \mb{Z}$ and one from $\mb{Y}$ to $H$ that is d-connecting given $\mb{X} \cup \mb{S} \cup \mb{Z}$. Let $p=\langle X, \ldots, H \rangle$, $X \in \mb{X}$, and $q=\langle H, \ldots, Y \rangle$, $Y \in \mb{Y}$, be such paths, respectively, where $p$ is proper. In the arguments below, we use paths related to $p$ and $q$ -- in the proper back-door graph $\dpbd{\mb{XY}}$ (see Definition \ref{def:pbd}) and in four of its moral induced subgraphs (see Definition \ref{def:moral}) -- before applying Theorems \ref{thm:richardson} and \ref{thm:ac-alt} to reach our final contradiction (that $\mb{S}$ cannot satisfy the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$).

First, we claim that both $p$ and $q$ are d-connecting given $\mb{S} \cup \mb{Z}$. This holds for $p$ by definition. For sake of contradiction, suppose that $q$ is blocked by $\mb{S} \cup \mb{Z}$. Since $q$ is d-connecting given $\mb{X} \cup \mb{S} \cup \mb{Z}$, it must contain a collider in $\mathrm{An}(\mb{X},\g[D]) \setminus \mathrm{An}(\mb{S} \cup \mb{Z},\g[D])$. Let $C$ be the closest collider to $Y$ on $q$ such that $C \in (\mathrm{An}(\mb{X},\g[D]) \setminus \mathrm{An}(\mb{S} \cup \mb{Z},\g[D])) \cup \mb{X}$, and let $r=\langle C,\ldots,X' \rangle, X' \in \mb{X}$, be a shortest causal path in $\g[D]$ from $C$ to $\mb{X}$. Then let $V$ be the node closest to $X'$ on $r$ that is also on $q(C,Y)$, and define the path $t=(-r)(X',V) \oplus q(V,Y)$. Note that $t$ is non-causal since either $(-r)(X',V)$ is of non-zero length or $X'=V=C$, so that $t$ is a path into $X'$. Further, by the definitions of $q$, $C$, and $r$, we have that $t$ is proper non-causal path from $\mb{X}$ to $\mb{Y}$ that is d-connecting given $\mb{S} \cup \mb{Z}$. But this contradicts that $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$.

Next, we prove that the sequence of nodes in $\gpbd[D]{XY}$ corresponding to $p$ forms a path. Note that since $p$ is proper, we only need to show that $p$ does not start with an edge $X \rightarrow W$, where $W$ is a node that lies on a proper causal path  in $\g[D]$ from $X$ to $\mb{Y}$. For sake of contradiction, suppose that $p$ starts with $X \rightarrow W$ for such a $W \in \fb{\g[D]}$. Note that $p$ cannot be causal from $X$ to $H$, since $H \notin \mathrm{De}(\mb{X},\g[D])$ by the definition of $\mb{H}$. Thus, $p$ is non-causal and there is a collider $C'$ on $p$ such that $C' \in \mathrm{De}(W,\g[D])$. Since $p$ is d-connecting given $\mb{S} \cup \mb{Z}$ and $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$, then $\mb{S} \cap \mathrm{De}(C',\g[D]) \neq \emptyset$. Further, since $\mathrm{De}(C',\g[D]) \subseteq \fb{\g[D]}$, this implies that $\mb{S} \cap \fb{\g[D]} \neq \emptyset$. But this contradicts that $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$.

Similarly, we prove that the sequence of nodes in $\gpbd[D]{XY}$ corresponding to $q$ also forms a path. For this, note that all nodes in $\mb{X}$ on $q$ must be a colliders on $q$, since $q$ is d-connecting given $\mb{X} \cup \mb{S} \cup \mb{Z}$. Thus, removing edges out of $\mb{X}$ from $\g[D]$ in order to form $\gpbd[D]{XY}$ will not affect the edges on $q$.

Let $\tilde{p}$ and $\tilde{q}$ be the paths in $\gpbd[D]{XY}$ corresponding to $p$ and $q$, respectively. Then for sake of contradiction, suppose either $\tilde{p}$ or $\tilde{q}$ is blocked given $\mb{S} \cup \mb{Z}$. Since $p$ and $q$ are d-connecting given $\mb{S} \cup \mb{Z}$, then there must be a node $C$ on $p$ or $q$ where $C$ is a collider on $p$ or $q$ and every causal path in $\g[D]$ from $C$ to $\mb{S} \cup \mb{Z}$ contains the first edge of a proper causal path from $\mb{X}$ to $\mb{Y}$ in $\g[D]$. Let $d$ be an arbitrary such causal path in $\g[D]$ from $C$ to $\mb{S} \cup \mb{Z}$. Note that $d$ is a path from $C$ to $\mb{S}$, since $d$ must contain a node in $\mb{X}$ and since $\mb{Z} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$. But since $d$ contains the first edge of a proper causal path from $\mb{X}$ to $\mb{Y}$ in $\g[D]$, this implies that $\mb{S} \cap \fb{\g[D]} \neq \emptyset$, which contradicts that $\mb{S}$ satisfies the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$.

We continue the base case by reasoning with four moral induced subgraphs of $\gpbd[D]{XY}$ (see Definition \ref{def:moral}). Start by defining the following. 
\begin{align}
    \mb{A}_{\mb{XHYSZ}} &= \mathrm{An}(\mb{X} \cup \mb{H} \cup \mb{Y} \cup \mb{S} \cup \mb{Z},\gpbd[D]{XY}). \nonumber \\
    \mb{A}_{\mb{XYSZ}} &= \mathrm{An}(\mb{X} \cup \mb{Y} \cup \mb{S} \cup \mb{Z},\gpbd[D]{XY}). \nonumber \\
    \mb{A}_{\mb{XHSZ}} &= \mathrm{An}(\mb{X} \cup \mb{H} \cup \mb{S} \cup \mb{Z},\gpbd[D]{XY}). \nonumber \\
    \mb{A}_{\mb{HYSZ}} &= \mathrm{An}(\mb{H} \cup \mb{Y} \cup \mb{S} \cup \mb{Z},\gpbd[D]{XY}). \nonumber 
\end{align} 
Then define $\g[D]_{\mb{XHYSZ}}$, $\g[D]_{\mb{XYSZ}}$, $\g[D]_{\mb{XHSZ}}$, and $\g[D]_{\mb{HYSZ}}$ to be the moral induced subgraphs of $\gpbd[D]{XY}$ on nodes $\mb{A}_{\mb{XHYSZ}}$, $\mb{A}_{\mb{XYSZ}}$, $\mb{A}_{\mb{XHSZ}}$, and $\mb{A}_{\mb{HYSZ}}$, respectively. In order to use Theorem \ref{thm:ac-alt}, we want to show that $\g[D]_{\mb{XYSZ}}$ contains a path from $\mb{X}$ to $\mb{Y}$ that does not contain a node in $\mb{S} \cup \mb{Z}$.

Since $\tilde{p}$ and $\tilde{q}$ are d-connecting given $\mb{S} \cup \mb{Z}$, then by Theorem \ref{thm:richardson}, the following two paths must exist in $\g[D]_{\mb{XHSZ}}$: path $a$ from $X$ to $H$ and path $b$ from $H$ to $Y$, where neither path contains a node in $\mb{S} \cup \mb{Z}$. Note that since $\mb{A}_{\mb{XHSZ}} \subseteq \mb{A}_{\mb{XHYSZ}}$ and $\mb{A}_{\mb{HYSZ}} \subseteq \mb{A}_{\mb{XHYSZ}}$, any path in $\g[D]_{\mb{XHSZ}}$ or $\g[D]_{\mb{HYSZ}}$ will also be in $\g[D]_{\mb{XHYSZ}}$. Further, since $H \in \mathrm{An}(\mb{X} \cup \mb{Y},\g[D])$ by definition and since we form $\gpbd[D]{XY}$ by removing edges out of $\mb{X}$ from $\g[D]$, then $H \in \mathrm{An}(\mb{X} \cup \mb{Y},\gpbd[D]{XY})$. Therefore, $\mb{A}_{\mb{XHYSZ}} = \mb{A}_{\mb{XYSZ}}$ and $\g[D]_{\mb{XHYSZ}}=\g[D]_{\mb{XYSZ}}$. Thus, $a$ and $b$ are both paths in $\g[D]_{\mb{XYSZ}}$.

We complete the base case by applying Theorems \ref{thm:richardson} and \ref{thm:ac-alt} to show our necessary contradiction. Since we can combine subpaths of $a$ and $b$ to form a path $c$ in $\g[D]_{\mb{XYSZ}}$ from $\mb{X}$ to $\mb{Y}$ that does not contain a node in $\mb{S} \cup \mb{Z}$, then by Theorem \ref{thm:richardson}, $\mb{X}$ and $\mb{Y}$ are d-connecting given $\mb{S} \cup \mb{Z}$ in $\gpbd[D]{XY}$. By Theorem \ref{thm:ac-alt}, this implies that $\mb{S} \cup \mb{Z}$ does not satisfy the adjustment criterion relative to $(\mb{X,Y})$ in $\g[D]$ (see Definition \ref{def:ac}). Therefore, by the contraposition of Lemma \ref{lem:comparison}\ref{lem:comparison-a}, $\mb{S}$ does not satisfy the conditional adjustment criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$, which is a contradiction.







