\label{def:cbc}
{\normalfont (\textbf{Conditional Back-door Criterion for DAGs})}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a DAG $\g[D]$, where $\mb{Z} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$. Then $\mb{S}$ satisfies the conditional back-door criterion relative to $(\mb{X},\mb{Y},\mb{Z})$ in $\g[D]$ if 
    \begin{enumerate}[label=\emph{(\alph*)}]
        \item $\mb{S} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$, and
        \item $\mb{S} \cup \mb{Z}$ blocks all proper back-door paths from $\mb{X}$ to $\mb{Y}$.
    \end{enumerate}

\begin{align}
        f(\mb{y}|do(\mb{x}),\mb{z}) &= \int_\mb{s} f(\mb{y},\mb{s}|do(\mb{x}),\mb{z}) \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
                     &= \int_\mb{s} f(\mb{y}|\mb{s},do(\mb{x}),\mb{z}) f(\mb{s}|do(\mb{x}),\mb{z}) \mathop{}\!\mathrm{d} \mb{s} \nonumber \\
                     &= \int_\mb{s} f(\mb{y}|\mb{s},\mb{x},\mb{z}) f(\mb{s}|\mb{z}) \mathop{}\!\mathrm{d} \mb{s} \nonumber
    \end{align}

\label{lem:gbc-cbc}
{\normalfont (\textbf{Comparison of Back-door Criteria for DAGs})}
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{S}$ be pairwise disjoint node sets in a DAG $\g[D]$, where $\mb{Z} \cap \mathrm{De}(\mb{X}, \g[D]) = \emptyset$. Then $\mb{S}$ satisfies the conditional back-door criterion relative to $(\mb{X,Y,Z})$ in $\g[D]$ (Definition \ref{def:cbc}) if and only if $\mb{S} \cup \mb{Z}$ satisfies the generalized back-door criterion relative to $(\mb{X}, \mb{Y})$ in $\g[D]$ (Definition \ref{def:gbc}).

\label{lem:concat}
    Let $X$, $Y$, and $Z$ be distinct nodes in an MPDAG $\g$.
    \begin{enumerate}[label=(\roman*)]
        \item \label{lem:concat-pc-p} 
        If $p$ is a possibly causal path from $X$ to $Y$ and $q$ is a causal path from $Y$ to $Z$, then $p \oplus q$ is a possibly causal path from $X$ to $Z$.

        \item \label{lem:concat-c-pc} 
        If $p$ is a causal path from $X$ to $Y$ and $q$ is a possibly causal path from $Y$ to $Z$, then $p \oplus q$ is a possibly causal path from $X$ to $Z$.
    \end{enumerate}

\label{lem:equiv-z-pag} 
    Let $\mb{X}$ and $\mb{Z}$ be disjoint node sets in a PAG $\g$. Then the following statements are equivalent.
    \begin{enumerate}[label = (\roman*)]
        \item $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$. \label{lem:equiv-z-pag-a}
        \item $\mb{Z} \cap \mathrm{De}(\mb{X},\g[D]) = \emptyset$ in every DAG $\g[D]$ represented by $\g$. \label{lem:equiv-z-pag-b}
    \end{enumerate}

